# app.R — Correlation Explorer (ShinyLive-ready, no "moat")
# Changes in this version: removed the summary card entirely (no Kendall/Spearman/Pearson panel)

library(shiny)
# --- Tokens ---------------------------------------------------------------
LIGHT_BLUE <- "#767da2"  # inputs + borders
ORANGE     <- "#cd6118"  # brand / primary
FG         <- "#e1e2ea"  # text on dark
AXIS       <- "#adbdd1"

# --- Theme + CSS ----------------------------------------------------------
app_css <- "
  :root{
    --bg:#1d1f2b;
    --fg:#e1e2ea;
    --accent:#cd6118;
    --secondary:#5a5f80;
    --input:#767da2;
    --axis:#adbdd1;
  }

  html{
    overflow-y:scroll !important;
    overflow-x:hidden !important;
  }

  body{
    position:static !important;
    height:auto !important;
    min-height:100% !important;
    max-height:none !important;
    overflow:visible !important;
    background:var(--bg) !important;
    color:var(--fg) !important;
    font-family:'Lexend',system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial,sans-serif !important;
  }

  .container-fluid{
    max-width:1100px;
    overflow:visible !important;
    background:var(--bg) !important;
    color:var(--fg) !important;
    padding-top:16px;
    padding-top:calc(16px + env(safe-area-inset-top));
    padding-bottom:18px;
    padding-bottom:calc(18px + env(safe-area-inset-bottom));
  }

  .shiny-input-container{margin-bottom:10px;}

  .no-stack{display:flex;gap:16px;align-items:flex-start;}
  .no-stack .left{flex:0 0 340px;min-width:260px;}
  .no-stack .right{flex:1 1 auto;min-width:0;}

  h2.title{
    font-size:20px;
    line-height:1.25;
    margin:6px 0 10px;
    font-weight:600;
    color:var(--fg) !important;
  }

  #plotBox{
    background:var(--bg) !important;
    border:1.5px solid var(--input) !important;
    padding:22px 24px 20px;
    border-radius:.6rem;
    box-shadow:none;
    margin-top:8px;
    width:100%;
    box-sizing:border-box;
    overflow:visible;
  }

  #scatter,#heatmap{
    width:100% !important;
    box-sizing:border-box;
  }

  .form-control,.form-select,.selectize-input,input[type=number]{
    background-color:var(--input) !important;
    color:var(--fg) !important;
    border:1px solid var(--input) !important;
    box-shadow:none !important;
  }

  .form-control:focus,.form-select:focus,.selectize-input.focus{
    border-color:var(--accent) !important;
    outline:0 !important;
    box-shadow:0 0 0 .15rem rgba(205,97,24,.35) !important;
  }

  .selectize-dropdown{
    background:#2b2f49 !important;
    color:var(--fg) !important;
    border-color:var(--secondary) !important;
  }

  .selectize-dropdown .active,.selectize-dropdown .option:hover{
    background:var(--secondary) !important;
    color:#fff !important;
  }

  .irs--shiny .irs-line{
    background:var(--secondary) !important;
    border-color:var(--secondary) !important;
  }

  .irs--shiny .irs-bar,
  .irs--shiny .irs-bar-edge{
    background:var(--input) !important;
    border-color:var(--input) !important;
  }

  .irs--shiny .irs-slider,
  .irs--shiny .irs-handle,
  .irs--shiny .irs-handle>i:first-child{
    background:var(--input) !important;
    border-color:var(--input) !important;
  }

  .irs--shiny .irs-single,
  .irs--shiny .irs-from,
  .irs--shiny .irs-to,
  .irs--shiny .irs-min,
  .irs--shiny .irs-max,
  .irs--shiny .irs-grid-text{
    color:var(--fg) !important;
  }

  details,summary,label,.control-label,.checkbox,.radio,table{
    color:var(--fg) !important;
  }

  table,th,td{
    background:var(--bg) !important;
    border-color:var(--input) !important;
  }

  #scatter img,#heatmap img{
    display:block;
    width:100%;
    height:auto !important;
  }

  @media (max-width:576px){
    .no-stack{flex-direction:column;gap:12px;}
    .no-stack .left,.no-stack .right{
      flex:1 1 100%;
      min-width:0;
      width:100%;
    }
    .container-fluid{padding-left:12px;padding-right:12px;}
    #plotBox{padding:16px 14px 14px;}
    h2.title{font-size:18px;}
  }
"

# --- Helpers --------------------------------------------------------------
extend_lr <- function(x, f = 0.04) {
  r <- range(x, na.rm = TRUE); d <- diff(r); c(r[1] - f*d, r[2] + f*d)
}

# Generate data: linear via correlated normals; non-linear via functions
gen_data <- function(mode, n, r, pattern, noise, seed) {
  set.seed(seed)
  if (mode == "continuous") {
    if (pattern == "Linear (bivariate normal)") {
      x <- rnorm(n)
      z <- rnorm(n)
      y <- r * x + sqrt(pmax(0, 1 - r^2)) * z
      data.frame(x, y)
    } else if (pattern == "Cubic") {
      x <- rnorm(n); y <- x^3 + rnorm(n, sd = noise); data.frame(x, y)
    } else if (pattern == "Quadratic") {
      x <- rnorm(n); y <- (x^2) + rnorm(n, sd = noise); y <- y - mean(y); data.frame(x, y)
    } else data.frame(x = numeric(0), y = numeric(0))
  } else NULL
}

safe_cor <- function(x, y, method) {
  out <- suppressWarnings(try(cor.test(x, y, method = method), silent = TRUE))
  if (inherits(out, "try-error")) return(list(estimate = NA_real_, p = NA_real_))
  list(estimate = unname(out$estimate), p = out$p.value)
}

phi_coef <- function(a, b, c, d) {
  den <- sqrt((a+b)*(c+d)*(a+c)*(b+d)); if (den == 0) return(NA_real_)
  (a*d - b*c) / den
}

# --- UI -------------------------------------------------------------------
ui <- fluidPage(
  tags$head(
    tags$style(HTML(app_css)),
    tags$link(rel = "preconnect", href = "https://fonts.googleapis.com"),
    tags$link(rel = "preconnect", href = "https://fonts.gstatic.com", crossorigin = "anonymous"),
    tags$link(
      href = "https://fonts.googleapis.com/css2?family=Lexend:wght@300;400;500&family=Recursive:wght,MONO@400,1&display=swap",
      rel  = "stylesheet"
    ),
    tags$script(src = "https://cdn.jsdelivr.net/npm/iframe-resizer/js/iframeResizer.contentWindow.min.js"),
    tags$script(HTML("
      document.addEventListener('shiny:idle', function(){
        if (window.parentIFrame && window.parentIFrame.size) window.parentIFrame.size();
      });
    ")),
    # No-moat helpers
    tags$script(HTML("
      (function () {
        function send() {
          if (!window.Shiny) return;
          Shiny.setInputValue('vh_px', window.innerHeight, {priority:'event'});
          Shiny.setInputValue('resizeTick', Date.now(),     {priority:'event'});
        }
        window.addEventListener('load', send, {once:true});
        document.addEventListener('shiny:connected', send);
        window.addEventListener('resize', send);
        window.addEventListener('orientationchange', send);
      })();
    ")),
    tags$script(HTML("
  document.addEventListener('shiny:connected', function () {

    Shiny.addCustomMessageHandler('setScatterH', function(px) {
      var el = document.getElementById('scatter');
      if (el) {
        el.style.height = String(px) + 'px';
      }
    });

    Shiny.addCustomMessageHandler('setHeatH', function(px) {
      var el = document.getElementById('heatmap');
      if (el) {
        el.style.height = String(px) + 'px';
      }
    });

  });
"))
  ),

  div(
    class = "no-stack",
    # LEFT
    div(
      class = "left",
      h2(class = "title", "Correlation Explorer"),
      radioButtons(
        "mode", "Data type",
        choices = c("Continuous (scatter)" = "continuous", "Binary (2×2, phi)" = "binary"),
        selected = "continuous"
      ),

      conditionalPanel(
        condition = "input.mode == 'continuous'",
        selectInput(
          "pattern", "Relationship pattern",
          choices = c(
            "Linear (bivariate normal)",
            "Quadratic",
            "Cubic"
          ),
          selected = "Linear (bivariate normal)", selectize = FALSE
        ),
        conditionalPanel(
          condition = "input.pattern == 'Linear (bivariate normal)'",
          sliderInput("r_target", "Target Pearson r", min = -0.99, max = 0.99, value = 0.6, step = 0.01)
        ),
        conditionalPanel(
          condition = "input.pattern != 'Linear (bivariate normal)'",
          sliderInput("noise", "Noise (SD of added noise)", min = 0, max = 1.5, value = 0.25, step = 0.05)
        ),
        sliderInput("n", "Sample size (n)", min = 20, max = 500, value = 200, step = 5),
        numericInput("seed", "Seed (for reproducibility)", value = 122, step = 1),
        checkboxInput("show_lm", "Show line of best fit (regression)", value = TRUE),
        checkboxInput("show_loess", "Show smooth (LOESS)", value = TRUE),
        tags$details(
          tags$summary("What to look for"),
          tags$ul(
            tags$li("Pearson r captures linear, directional association."),
            tags$li("Spearman rho is rank-based; it can reveal monotonic but non-linear association."),
            tags$li("Some strong non-linear patterns (e.g., Quadratic) can have r \u2248 0.")
          )
        )
      ),

      conditionalPanel(
        condition = "input.mode == 'binary'",
        numericInput("a", "Cell a (1,1)", value = 30, min = 0, step = 1),
        numericInput("b", "Cell b (1,0)", value = 10, min = 0, step = 1),
        numericInput("c", "Cell c (0,1)", value = 10, min = 0, step = 1),
        numericInput("d", "Cell d (0,0)", value = 30, min = 0, step = 1),
        tags$details(
          tags$summary("Phi coefficient"),
          tags$ul(
            tags$li("Phi is Pearson's correlation applied to two binary variables."),
            tags$li("It relates to the chi-square test of independence.")
          )
        )
      )
    ),

    # RIGHT
    div(
      class = "right",
      div(
        id = "plotBox",
        conditionalPanel(condition = "input.mode == 'continuous'", plotOutput("scatter")),
        conditionalPanel(condition = "input.mode == 'binary'",     plotOutput("heatmap"))
      ),
      conditionalPanel(condition = "input.mode == 'binary'", div(id = "bin_table", tableOutput("contingency_table")))
    )
  )
)

# --- Server ---------------------------------------------------------------
server <- function(input, output, session) {

  # ----- dynamic heights (no-moat) -----
  scatterHeight <- reactive({
    w <- session$clientData$output_scatter_width
    if (is.null(w) || !is.finite(w) || w <= 0) w <- 600
    compact  <- (w < 520)
    h_from_w <- if (compact) max(260, 0.56 * w) else max(300, min(560, 0.62 * w))
    vh <- input$vh_px
    if (is.numeric(vh) && is.finite(vh) && vh > 0) {
      cap <- if (compact) 0.58 * vh else 0.66 * vh
      h_from_w <- min(h_from_w, cap)
    }
    round(h_from_w)
  })
  heatHeight <- reactive({
    w <- session$clientData$output_heatmap_width
    if (is.null(w) || !is.finite(w) || w <= 0) w <- 520
    compact  <- (w < 520)
    h_from_w <- if (compact) max(240, 0.50 * w) else max(280, min(520, 0.56 * w))
    vh <- input$vh_px
    if (is.numeric(vh) && is.finite(vh) && vh > 0) {
      cap <- if (compact) 0.54 * vh else 0.62 * vh
      h_from_w <- min(h_from_w, cap)
    }
    round(h_from_w)
  })
  observeEvent(list(scatterHeight(), input$resizeTick), {
    session$sendCustomMessage("setScatterH", scatterHeight())
  }, ignoreInit = FALSE)
  observeEvent(list(heatHeight(), input$resizeTick), {
    session$sendCustomMessage("setHeatH", heatHeight())
  }, ignoreInit = FALSE)

  # ----------------------------- CONTINUOUS -------------------------------
  dat_cont <- reactive({
    req(input$mode == "continuous")
    n     <- as.integer(input$n)
    seed  <- as.integer(input$seed)
    patt  <- input$pattern
    r     <- if (!is.null(input$r_target)) as.numeric(input$r_target) else 0
    noise <- if (!is.null(input$noise)) as.numeric(input$noise) else 0.25
    gen_data("continuous", n, r, patt, noise, seed)
  })

  # keep for Pearson annotation on scatter
  cont_stats <- reactive({
    df <- dat_cont()
    if (!nrow(df)) return(NULL)
    list(
      pear  = safe_cor(df$x, df$y, method = "pearson"),
      spear = safe_cor(df$x, df$y, method = "spearman"),
      kend  = safe_cor(df$x, df$y, method = "kendall")
    )
  })

  output$scatter <- renderPlot({
    df <- dat_cont()
    validate(need(nrow(df) > 1, "Not enough data to plot."))

    xr <- extend_lr(df$x)
    yr <- extend_lr(df$y)

    op <- par(no.readonly = TRUE)
    on.exit(par(op), add = TRUE)

    par(
      bg = "#1d1f2b",
      fg = FG,
      col.axis = FG,
      col.lab = FG,
      col.main = FG,
      mar = c(4.6, 4.8, 3.2, 1.2),
      mgp = c(2.6, 0.8, 0)
    )

    plot(
      df$x, df$y,
      xlim = xr, ylim = yr,
      xlab = "X", ylab = "Y",
      main = input$pattern,
      pch = 16,
      cex = 0.9,
      col = FG,
      axes = FALSE
    )

    axis(1, col = AXIS, col.axis = FG)
    axis(2, col = AXIS, col.axis = FG)
    box(col = AXIS)

    if (isTRUE(input$show_lm)) {
      fit <- tryCatch(lm(y ~ x, data = df), error = function(e) NULL)
      if (!is.null(fit)) {
        abline(fit, lwd = 2.4, col = ORANGE)
      }
    }

    if (isTRUE(input$show_loess)) {
      smooth_fit <- tryCatch(
        loess(y ~ x, data = df),
        error = function(e) NULL
      )

      if (!is.null(smooth_fit)) {
        xs <- seq(min(df$x), max(df$x), length.out = 300)
        pred <- tryCatch(
          predict(smooth_fit, newdata = data.frame(x = xs)),
          error = function(e) rep(NA_real_, length(xs))
        )
        ok <- is.finite(pred)
        if (any(ok)) {
          lines(
            xs[ok], pred[ok],
            lwd = 2.6,
            lty = 5,
            col = "#8a1e00"
          )
        }
      }
    }

    st <- cont_stats()
    if (!is.null(st) && is.finite(st$pear$estimate)) {
      label <- sprintf("Pearson r = %.3f", st$pear$estimate)
      text(
        x = xr[1] + 0.02 * diff(xr),
        y = yr[2] - 0.03 * diff(yr),
        labels = label,
        adj = c(0, 1),
        col = FG,
        cex = 1.05
      )
    }
  },
  width = function() {
    w <- session$clientData$output_scatter_width
    if (is.null(w) || !is.finite(w) || w <= 0) w <- 600
    round(max(320, min(1100, w)))
  },
  height = function() scatterHeight(),
  res = 96,
  execOnResize = TRUE,
  bg = "#1d1f2b"
  )

  # ------------------------------- BINARY ---------------------------------
  bin_counts <- reactive({
    req(input$mode == "binary")
    a <- as.integer(input$a); b <- as.integer(input$b)
    c <- as.integer(input$c); d <- as.integer(input$d)
    if (any(!is.finite(c(a,b,c,d)))) return(NULL)
    list(a = a, b = b, c = c, d = d)
  })

  bin_stats <- reactive({
    bc <- bin_counts(); if (is.null(bc)) return(NULL)
    mat <- matrix(c(bc$a, bc$b, bc$c, bc$d), nrow = 2, byrow = TRUE)
    dimnames(mat) <- list(Row = c("1", "0"), Col = c("1", "0"))
    chisq <- suppressWarnings(try(chisq.test(mat, correct = FALSE), silent = TRUE))
    phi   <- phi_coef(bc$a, bc$b, bc$c, bc$d)
    list(
      mat = mat, phi = phi,
      chi2 = if (!inherits(chisq, "try-error")) chisq$statistic else NA_real_,
      df   = if (!inherits(chisq, "try-error")) chisq$parameter else NA_real_,
      p    = if (!inherits(chisq, "try-error")) chisq$p.value   else NA_real_
    )
  })

  output$heatmap <- renderPlot({
    st <- bin_stats()
    validate(need(!is.null(st), "Enter cell counts."))

    mat <- st$mat
    total <- sum(mat)
    prop <- if (is.finite(total) && total > 0) mat / total else matrix(0, 2, 2)

    op <- par(no.readonly = TRUE)
    on.exit(par(op), add = TRUE)

    par(
      bg = "#1d1f2b",
      fg = FG,
      col.axis = FG,
      col.lab = FG,
      col.main = FG,
      mar = c(4.6, 4.8, 4.2, 1.2),
      mgp = c(2.6, 0.8, 0)
    )

    palette <- colorRampPalette(c("#8a1e00", "#e57726"))(100)
    z <- t(prop[nrow(prop):1, , drop = FALSE])

    image(
      x = seq_len(ncol(mat)),
      y = seq_len(nrow(mat)),
      z = z,
      col = palette,
      axes = FALSE,
      xlab = "Column",
      ylab = "Row",
      main = "2×2 table (counts)"
    )

    axis(1, at = 1:2, labels = colnames(mat), col = AXIS, col.axis = FG)
    axis(2, at = 1:2, labels = rev(rownames(mat)), col = AXIS, col.axis = FG)
    box(col = AXIS)

    for (row in seq_len(nrow(mat))) {
      for (col in seq_len(ncol(mat))) {
        text(
          x = col,
          y = nrow(mat) - row + 1,
          labels = mat[row, col],
          col = "#000000",
          font = 2,
          cex = 1.5
        )
      }
    }

    subtitle_text <- if (is.finite(st$phi)) {
      sprintf("Phi = %.3f", st$phi)
    } else {
      "Phi = NA"
    }

    mtext(subtitle_text, side = 3, line = 0.4, col = FG, cex = 1.05)
  },
  width = function() {
    w <- session$clientData$output_heatmap_width
    if (is.null(w) || !is.finite(w) || w <= 0) w <- 520
    round(max(320, min(1100, w)))
  },
  height = function() heatHeight(),
  res = 96,
  execOnResize = TRUE,
  bg = "#1d1f2b"
  )

  output$contingency_table <- renderTable({
    st <- bin_stats(); if (is.null(st)) return(NULL)
    addmargins(st$mat)
  }, bordered = TRUE, striped = FALSE, spacing = "xs")
}

shinyApp(ui, server)
